    'TypeID', p_TypeID_2ecbdcf684fc,
    'TemplateText', p_TemplateText_2ecbdcf684fc,
    'Priority', p_Priority_2ecbdcf684fc,
    'IsActive', p_IsActive_2ecbdcf684fc
  ));
    ELSE
      PERFORM __mj."spCreateTemplateContent"(p_ID := p_ID_2ecbdcf684fc, p_TemplateID := p_TemplateID_2ecbdcf684fc, p_TypeID := p_TypeID_2ecbdcf684fc, p_TemplateText := p_TemplateText_2ecbdcf684fc, p_Priority := p_Priority_2ecbdcf684fc, p_IsActive := p_IsActive_2ecbdcf684fc);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateTemplateContent'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
