    'TypeID', p_TypeID_5242422895c4,
    'TemplateText', p_TemplateText_5242422895c4,
    'Priority', p_Priority_5242422895c4,
    'IsActive', p_IsActive_5242422895c4
  ));
    ELSE
      PERFORM __mj."spCreateTemplateContent"(p_ID := p_ID_5242422895c4, p_TemplateID := p_TemplateID_5242422895c4, p_TypeID := p_TypeID_5242422895c4, p_TemplateText := p_TemplateText_5242422895c4, p_Priority := p_Priority_5242422895c4, p_IsActive := p_IsActive_5242422895c4);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateTemplateContent'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
    ) THEN
