    'TemplateText', p_TemplateText_ef4a0ff57bec,
    'Priority', p_Priority_ef4a0ff57bec,
    'IsActive', p_IsActive_ef4a0ff57bec
  ));
    ELSE
      PERFORM __mj."spCreateTemplateContent"(p_ID := p_ID_ef4a0ff57bec, p_TemplateID := p_TemplateID_ef4a0ff57bec, p_TypeID := p_TypeID_ef4a0ff57bec, p_TemplateText := p_TemplateText_ef4a0ff57bec, p_Priority := p_Priority_ef4a0ff57bec, p_IsActive := p_IsActive_ef4a0ff57bec);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateTemplateContent'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
