  p_ContextCompressionMessageRetentionCount_5f0af2b401e3 INTEGER;
  p_ContextWindowMaxTokens_5f0af2b401e3 INTEGER;
  p_CompactionTriggerPercent_5f0af2b401e3 INTEGER;
  p_CompactionTargetPercent_5f0af2b401e3 INTEGER;
