DECLARE
  p_ID_af9b61155d8e UUID;
  p_Name_af9b61155d8e VARCHAR(255);
  p_CategoryID_af9b61155d8e UUID;
  p_UserQuestion_af9b61155d8e TEXT;
  p_Description_af9b61155d8e TEXT;
  p_SQL_af9b61155d8e TEXT;
  p_TechnicalDescription_af9b61155d8e TEXT;
  p_OriginalSQL_af9b61155d8e TEXT;
  p_Feedback_af9b61155d8e TEXT;
  p_Status_af9b61155d8e VARCHAR(15);
  p_QualityRank_af9b61155d8e INTEGER;
  p_ExecutionCostRank_af9b61155d8e INTEGER;
  p_UsesTemplate_af9b61155d8e BOOLEAN;
  p_AuditQueryRuns_af9b61155d8e BOOLEAN;
  p_CacheEnabled_af9b61155d8e BOOLEAN;
  p_CacheTTLMinutes_af9b61155d8e INTEGER;
  p_CacheMaxSize_af9b61155d8e INTEGER;
