  p_EmbeddingModelID_af9b61155d8e UUID;
  p_CacheValidationSQL_af9b61155d8e TEXT;
  p_SQLDialectID_af9b61155d8e UUID;
  p_Reusable_af9b61155d8e BOOLEAN;
  p_ExternalDataSourceID_af9b61155d8e UUID;
  p_IsMaterialized_af9b61155d8e BOOLEAN;
  p_Configuration_af9b61155d8e TEXT;
BEGIN
  p_ID_af9b61155d8e := '4513AE64-76A5-432C-BA67-360C8A97753F';
  p_Name_af9b61155d8e := 'RubricDriftPeriodMeans';
  p_CategoryID_af9b61155d8e := '5609FBC7-381C-4F9C-9C74-04B52C1FF3DA';
  p_UserQuestion_af9b61155d8e := 'How did each agent''s rubric criterion mean change between the last two periods?';
  p_Description_af9b61155d8e := 'Mean normalized score per agent, rubric, and criterion for two time windows. Counts only Submitted evaluations that are not self-checks, and only the evaluator''s own scores.';
  p_SQL_af9b61155d8e := '-- Per-agent, per-rubric, per-criterion means for the two drift windows.
-- Submitted evaluations only. Self-checks are left out. Group rollups are left out.
-- The client renders AgentName, RubricName, and CriterionKey. It does not read raw score rows.
SELECT
    agent.[Name] AS AgentName,
    rubric.[Name] AS RubricName,
    criterion.[Key] AS CriterionKey,
    AVG(CASE
        WHEN evaluation.[SubmittedAt] >= {{ currentStart | sqlDate }}
         AND evaluation.[SubmittedAt] < {{ periodEnd | sqlDate }}
        THEN score.[NormalizedScore]
    END) AS CurrentMean,
    AVG(CASE
        WHEN evaluation.[SubmittedAt] >= {{ previousStart | sqlDate }}
         AND evaluation.[SubmittedAt] < {{ currentStart | sqlDate }}
        THEN score.[NormalizedScore]
    END) AS PreviousMean
FROM [__mj].[RubricEvaluationScore] score
INNER JOIN [__mj].[RubricEvaluation] evaluation ON evaluation.[ID] = score.[EvaluationID]
INNER JOIN [__mj].[RubricVersion] version ON version.[ID] = evaluation.[RubricVersionID]
INNER JOIN [__mj].[Rubric] rubric ON rubric.[ID] = version.[RubricID]
INNER JOIN [__mj].[RubricCriterion] criterion ON criterion.[ID] = score.[CriterionID]
INNER JOIN [__mj].[AIAgentRun] run ON run.[ID] = TRY_CONVERT(UUID, evaluation.[SubjectRecordID])
INNER JOIN [__mj].[AIAgent] agent ON agent.[ID] = run.[AgentID]
WHERE evaluation.[Status] = ''Submitted''
  AND evaluation.[EvaluatorType] <> ''Self''
  AND score.[IsComputed] = 0
  AND score.[NormalizedScore] IS NOT NULL
  AND evaluation.[SubmittedAt] >= {{ previousStart | sqlDate }}
  AND evaluation.[SubmittedAt] < {{ periodEnd | sqlDate }}
GROUP BY agent.[Name], rubric.[Name], criterion.[Key]
';
  p_TechnicalDescription_af9b61155d8e := 'Groups RubricEvaluationScore by AI Agent name, Rubric name, and criterion Key. previousStart, currentStart, and periodEnd ({{ previousStart | sqlDate }}, {{ currentStart | sqlDate }}, {{ periodEnd | sqlDate }}) bound the two windows [previousStart, currentStart) and [currentStart, periodEnd). Status is Submitted and EvaluatorType is not Self.';
  p_Status_af9b61155d8e := 'Approved';
  p_QualityRank_af9b61155d8e := 8;
  p_ExecutionCostRank_af9b61155d8e := 3;
  p_UsesTemplate_af9b61155d8e := TRUE;
  p_AuditQueryRuns_af9b61155d8e := FALSE;
