  p_InputTypeDefinition_ed610355e660 := '/** Input for `Workflow.Draft`. */
export interface WorkflowDraftInput {
    /** What the person wants done, in their own words. */
    description: string;
    /** What to call the workflow. Carried through to the draft''s `workflowName`. */
    workflowName: string;
}';
  p_InputTypeIsArray_ed610355e660 := FALSE;
  p_OutputTypeName_ed610355e660 := 'WorkflowDraftOutput';
  p_OutputTypeDefinition_ed610355e660 := '/** Output of `Workflow.Draft`. */
export interface WorkflowDraftOutput {
    /** True when a structurally valid draft came back. */
    success: boolean;
